import { householdSavingRows,householdSavingSource } from './planning-saving-rate-data.js';
export const savingRateDefinitions={
  householdSaving:{title:'Read the aggregate data, then define a separate personal cash budget',fields:[
    ['income','Hypothetical monthly net cash income (CAD)',6000,0,20000,100],
    ['living','Monthly living costs, excluding principal and listed irregular bills (CAD)',4200,0,15000,100],
    ['debtPrincipal','Monthly required debt-principal payment, entered separately (CAD)',300,0,3000,50],
    ['annualBills','Predictable irregular bills per year, excluded from living costs (CAD)',3600,0,36000,300],
    ['goal','Requested monthly transfer to a separate saving goal (CAD)',500,0,5000,50]
  ]}
};
export function householdCashBudget(input){
  const irregular=input.annualBills/12,capacity=input.income-input.living-input.debtPrincipal-irregular;
  return {irregular,capacity,residual:capacity-input.goal,requestedShare:input.income>0?input.goal/input.income:null};
}
export function savingRateResult(kind,input){
  if(kind!=='householdSaving')throw Error('Unknown saving-rate topic.');
  const p=householdCashBudget(input),latest=householdSavingRows.at(-1),source=householdSavingSource;
  return {metrics:[['Cash after the selected bills, before goal transfer',p.capacity,'money'],['Requested monthly goal transfer',input.goal,'money'],['Cash after the requested transfer',p.residual,'money']],note:'The first two figures are fixed public Statistics Canada observations, released 28 August 2026 and retrieved 25 October 2026. They do not change when personal inputs change. The last two are hypothetical monthly cash budgets with a different definition and population: entered net receipts minus living costs, separate debt principal, one-twelfth of predictable annual bills and a requested saving transfer. No tax calculation, investment return, pension accrual or borrowing is assumed. Negative residuals are unfunded commitments; the transfer is requested, not automatically affordable.',charts:[
    {id:'household-saving-rate-history',type:'line',title:'Canada’s household saving rate: twelve quarterly observations',unit:'percent',unitLabel:'Percent of household disposable income; quarterly, seasonally adjusted',xLabel:'Calendar quarter',xTicks:[0,5,11].map(index=>({value:index,label:householdSavingRows[index].quarter.replace('-',' ')})),series:[{name:'Published household saving rate',rows:householdSavingRows.map((row,index)=>({x:index,label:row.quarter.replace('-',' '),value:row.rate/100}))}],source:source.url,sourceLabel:'Statistics Canada · Table 36-10-0112-01 · released 28 August 2026',evidence:'Official statistics',note:'Canada, 2023 Q3 to 2026 Q2. Source dimension: seasonally adjusted at annual rates. Published saving-rate percentages are ratios, not annual investment returns and must not be multiplied by four. Retrieved 25 October 2026; historical observations can be revised.'},
    {id:'household-saving-national-accounts-bridge',type:'waterfall',title:'Reconcile household net saving in 2026 Q2',unit:'billions',unitLabel:'CAD billions, seasonally adjusted at annual rates',tableUnit:'CAD billions, seasonally adjusted at annual rates',rows:[{label:'Household disposable income',value:latest.income/1000},{label:'Less final consumption expenditure',value:-latest.consumption/1000},{label:'Plus change in pension entitlements',value:latest.pension/1000}],totalLabel:'Household net saving',source:source.url,sourceLabel:'Statistics Canada · Table 36-10-0112-01 · 2026 Q2',evidence:'Derived from official statistics',note:'Original flows are in CAD millions and divided by 1,000 here. Data-table amounts retain three decimal places of billions, preserving the source millions. These annualized accounting flows are not literal quarterly bank receipts. Net saving includes a pension-entitlement adjustment.'},
    {id:'household-saving-personal-cash-bridge',type:'waterfall',title:'A separate hypothetical monthly cash budget',unit:'money',unitLabel:'CAD per month; one hypothetical household',rows:[{label:'Net cash income received',value:input.income},{label:'Living costs',value:-input.living},{label:'Required debt-principal payments',value:-input.debtPrincipal},{label:'Reserve for predictable annual bills',value:-p.irregular},{label:'Requested saving-goal transfer',value:-input.goal}],totalLabel:'Unallocated cash, or unfunded gap',evidence:'Hypothetical scenario',note:'This is a personal cash ledger, not an estimate of the national-accounts saving rate. Debt principal and the annual-bill reserve are entered separately to avoid counting them inside living costs twice. A negative endpoint means the requested plan needs funding or revision.'},
    {id:'household-saving-personal-budget-matrix',type:'heatmap',title:'Cash left after different incomes and requested saving transfers',unit:'money',signed:true,columns:['$250 goal','$500','$1k','$1.5k'],rows:[4000,5000,6000,8000].map(income=>({label:'$'+income/1000+'k income',values:[250,500,1000,1500].map(goal=>householdCashBudget({...input,income,goal}).residual)})),evidence:'Hypothetical scenario',note:'Rows replace monthly net cash income; columns replace the requested monthly saving transfer. Selected living costs, debt principal and annual-bill reserve remain fixed. Cells are monthly cash residuals, not saving-rate statistics or recommended targets.'}
  ]};
}
